using HRM.Api.Infrastructure;
using HRM.DTOs.Leadership;
using HRM.Services.Contracts;
using Microsoft.AspNetCore.Mvc;
namespace HRM.Api.Controllers.V1;
[Route("api/v1/leadership-authority")]
public sealed partial class LeadershipAuthorityController(LeadershipAuthorityServiceContracts.IOperations service, LeadershipAdministrationServiceContracts.IOperations administration) : HrmApiController
{ [HttpGet("organisations")] public async Task<ActionResult<IReadOnlyList<LeadershipOrganisationAccessDto>>> Organisations(CancellationToken ct)=>Ok(await service.GetCurrentOrganisationAccessAsync(ct)); [HttpGet("appointments")] public async Task<ActionResult<IReadOnlyList<LeadershipAppointmentSummaryDto>>> Appointments(CancellationToken ct)=>Ok(await service.GetMyAppointmentsAsync(ct)); [HttpPost("appointment-types")] public async Task<ActionResult<global::HRM.DTOs.ServiceResult>> SaveAppointmentType([FromBody] LeadershipRequest<LeadershipAppointmentTypeInput> request,CancellationToken ct)=>Ok(await administration.SaveAppointmentTypeAsync(request.Input,ct)); [HttpPost("appointments")] public async Task<ActionResult<global::HRM.DTOs.ServiceResult>> SaveAppointment([FromBody] LeadershipRequest<LeadershipAppointmentInput> request,CancellationToken ct)=>Ok(await administration.SaveAppointmentAsync(request.Input,ct)); [HttpPost("responsibilities")] public async Task<ActionResult<global::HRM.DTOs.ServiceResult>> AddResponsibility([FromBody] LeadershipRequest<LeadershipResponsibilityInput> request,CancellationToken ct)=>Ok(await administration.AddResponsibilityAsync(request.Input,ct)); [HttpPost("authority-grants")] public async Task<ActionResult<global::HRM.DTOs.ServiceResult>> AddAuthorityGrant([FromBody] LeadershipRequest<LeadershipAuthorityGrantInput> request,CancellationToken ct)=>Ok(await administration.AddAuthorityGrantAsync(request.Input,ct)); [HttpPost("delegations")] public async Task<ActionResult<global::HRM.DTOs.ServiceResult>> AddDelegation([FromBody] LeadershipRequest<LeadershipDelegationInput> request,CancellationToken ct)=>Ok(await administration.AddDelegationAsync(request.Input,ct)); [HttpPost("attendance-policies")] public async Task<ActionResult<global::HRM.DTOs.ServiceResult>> SaveAttendancePolicy([FromBody] LeadershipRequest<LeadershipAttendancePolicyInput> request,CancellationToken ct)=>Ok(await administration.SaveAttendancePolicyAsync(request.Input,ct));  public sealed class LeadershipRequest<T> { public T Input { get; set; } = default!; } }
